"""Build the task's static canvas from inspected evidence; no deployment or science changes."""
from pathlib import Path
import json,shutil,html
R=Path('/astro/armin/koji/syndiff/dev_runs/s24_temporal_measurement_20261016');OUT=R/'canvas';OUT.mkdir(exist_ok=True)
figs=sorted((R/'figures').glob('*.png'))
for p in figs:shutil.copy2(p,OUT/p.name)
prepared=len(list((R/'frames').glob('*/PREPARED')));fitted=len(list((R/'frames').glob('*/wcs_fit/DONE')));exported=len(list((R/'frames').glob('*/native.npz')))
available=[int(p.stem.split('f')[-1]) for p in figs if p.stem.startswith('native_f')]
options=''.join(f'<option value="{i:04d}">FFI {i}</option>' for i in available)
fit_gallery=f'<label for="frame">Exposure: </label><select id="frame">{options}</select><figure><img id="native" alt="Native data, all-source model and residuals"><figcaption>Same source IDs and reference-flux scales. Masked pixels are blank. Residuals use one common scale.</figcaption></figure><figure><img id="response" alt="Native residual, local shape/shift response, and remainder"><figcaption>Local response is a diagnostic, not a selected temporal law. It includes amplitude and background freedom; a separate checkerboard test evaluates held pixels.</figcaption></figure>' if available else '<p>Per-exposure fit/residual exports are pending. The native input images below are observed data, not fitted residuals.</p>'
def fig(name,caption):
 return f'<figure><a href="{name}"><img src="{name}" alt="{html.escape(caption)}"></a><figcaption>{html.escape(caption)}</figcaption></figure>' if (OUT/name).exists() else ''
text='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>S24 C2K2 temporal WCS and PSF measurement</title><style>body{font:17px/1.6 system-ui,sans-serif;margin:auto;max-width:1250px;padding:25px;color:#163044;background:#f4f7fa}h1,h2{line-height:1.2}section{background:white;border:1px solid #d9e3eb;border-radius:10px;padding:24px;margin:22px 0}img{max-width:100%;max-height:850px;object-fit:contain;display:block;margin:auto}figure{margin:22px 0}figcaption,.small{font-size:14px;color:#4c6475}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:9px;border-bottom:1px solid #ddd}select{padding:9px;font-size:16px}code{overflow-wrap:anywhere}a{color:#006697}.status{padding:15px;background:#fff4d6;border-radius:8px}nav{display:flex;gap:20px;flex-wrap:wrap}</style></head><body>
<h1>S24 C2K2: temporal WCS and PSF measurements</h1><p>Both orbits · October 16, 2026 · Measurement before temporal-model selection</p>
'''
text+=f'<p class="status"><strong>Running:</strong> {prepared}/24 inputs prepared; {fitted}/24 first-pass WCS fits complete; {exported}/24 native residual exports. No final temporal mode or flat-light-curve result is accepted.</p>'
text+='''<nav><a href="#images">Native images</a><a href="#residuals">Fits and residuals</a><a href="#measurements">Temporal measurements</a><a href="#method">Method and limits</a></nav>
<section><h2>Question</h2><p>How do image positions and stellar profiles change across the two orbits, when measured with our current single-FFI radial/coma colour model and jointly fitted faint neighbours?</p><p>The model is not forced to follow a spline, temperature or jitter during this measurement. Each exposure has free WCS coefficients and source fluxes. The first pass holds the current reference PSF fixed; its remaining native-pixel residuals are then tested for local shift and shape responses.</p></section>
<section id="images"><h2>Exposure selection and actual input images</h2>'''
text+=fig('exposure_selection.png','Selection uses timing and telemetry before photometric scoring: 12 exposures per orbit, including startups, endpoints, high jitter and adjacent controls. Quality-zero exposures are shown.')
text+=fig('native_input_stamps.png','Actual native FFI stamps at four selected times. A local annulus is removed for display only. Each row shares the reference-frame peak scale; observed pixels have not been resampled. Click for full resolution.')
text+='</section><section id="residuals"><h2>Actual fitted images and residuals</h2>'+fig('native_gpu_wcs_f0602.png','Reference FFI 602: completed GPU WCS-only stage, fluxes evaluated locally at that checkpoint. Shape is held fixed; this is not the later full-PSF control.')+fit_gallery+'</section><section id="measurements"><h2>Measured changes</h2>'
text+=fig('wcs_fields.png','Spatial displacement maps relative to FFI 602. These are consistent model-origin positions, conditional on the reference PSF, not absolute astrometric truth.')
text+=fig('temporal_tracks.png','Descriptive position and residual-shape histories. The star-half comparison checks reproducibility; it is not an independently trained WCS validation.')
text+=fig('residual_stack_history.png','Underlying residual images and reference differences on a shared colour scale. Rasterization is for display and does not supply additional subpixel information.')
text+=fig('shape_response_tracks.png','Native-pixel equivalent covariance/shift changes and conditional held-pixel prediction. These are local diagnostics, not a fitted temporal mode or a certified optical mechanism.')
text+=fig('response_operator_check.png','Renderer calibration: native model profiles and finite-grid curvature responses. Tiny-step curvature is unreliable for the piecewise-linear interpolation; the measurement uses separate position and Richardson-corrected grid-scale shape responses.')
text+='''</section><section id="method"><h2>Method and limits</h2><table><tr><th>Component</th><th>Contract</th></tr><tr><td>Code</td><td>Isolated main-based branch <code>codex/s24-temporal-measurement-20261016</code>, based on 278461c1. Live production checkout untouched.</td></tr><tr><td>PSF and sources</td><td>Run5 <code>paper1_final_step1</code> radial/coma colour model; verified assoc_r2 removed neighbours to T=17. Original 18,334 source identities, including 6,857 nuisance sources, retained.</td></tr><tr><td>Image generation</td><td>Current calibrated F=4 bootstrap template, exposure-specific Hotpants kernel and rf5 background policy. These are preliminary images, not a completed temporal per-band final-image chain. Only the smooth background seed/mask geometry is transported; science pixels stay native.</td></tr><tr><td>Reference checks</td><td>Accepted-background replay agrees within floating-point representation; exact zero-time replay of baked source geometry. Differential proper motion is applied without changing the reference projection convention.</td></tr><tr><td>Masks</td><td>Science-fit support retains bright-star cores; kernel-fit exclusion flags are not science rejection masks. All exposures share scored support after finite/dynamic/defect checks.</td></tr><tr><td>Local response</td><td>Per-exposure profile derivatives measure shifts and three second-order shape responses, with amplitude/background free. Detector checkerboard halves compare held-pixel prediction with and without shape terms. Known-shift/blur analytic Gaussian integration tests pass; this does not certify the real PSF model.</td></tr></table>
<p>Remaining attribution checks include shape–position coupling, independent source groups, static-profile/subpixel sampling errors, template/background sensitivity, and variability preservation. Lower residuals alone do not establish unbiased fluxes. No per-star detrending or constant-flux constraint is applied.</p>
<details><summary>Preflight corrections</summary><p>A provisional alternative background seed was archived and abandoned before science fitting. The draft measurement harness also confused Hotpants kernel-fit flags with science support; a population-retention check caught the lost stellar cores, and support was corrected before fits. Missing proper motions remain recorded rather than invented.</p></details>
<p class="small">Durable record: /astro/armin/koji/syndiff/dev_runs/s24_temporal_measurement_20261016/README.md. DAG 7970, plscience3 schedd. This page is a saved checkpoint, not a live scheduler dashboard.</p></section>
<section><h2>Conclusion at this checkpoint</h2><p>The campaign is measuring the data before selecting a temporal model. Prepared inputs and diagnostics do not yet establish a sufficient WCS/PSF law or a light-curve precision floor. Inspect the native residuals and complete the remaining controls before making that decision.</p></section>
'''
responses=[i for i in available if (OUT/f'response_f{i:04d}.png').exists()]
if available:text+='<script>const responses='+json.dumps([f'{i:04d}' for i in responses])+';</script>'+'''<script>const s=document.getElementById('frame');function update(){document.getElementById('native').src='native_f'+s.value+'.png';const r=document.getElementById('response');r.parentElement.hidden=!responses.includes(s.value);if(responses.includes(s.value))r.src='response_f'+s.value+'.png'}s.addEventListener('change',update);update();</script>'''
text+='</body></html>';(OUT/'index.html').write_text(text)
print(OUT/'index.html',prepared,fitted,exported)
